from django.db import migrations

MODULES = [["Foundations of Public Speaking",[["What Makes a Speech Effective?","# What Makes a Speech Effective?\nPublic speaking is the intentional communication of an idea to an audience. It is not the absence of nervousness; it is the ability to deliver a useful message even when you feel nervous.\n\n## The three pillars\n**Purpose:** Decide what the audience should know, feel, or do after listening. A speech without a clear purpose often becomes a list of unrelated thoughts.\n\n**Audience:** Consider the listeners' knowledge, expectations, language, and concerns. A technical explanation for classmates will differ from a proposal to community leaders.\n\n**Message:** Reduce the central argument to one sentence. For example: 'Every student should learn basic digital safety because it protects their studies, finances, and privacy.'\n\n## The communication loop\nA speaker encodes a message into words, voice, and gestures. Listeners interpret that message through their own experiences. Noise—poor audio, distractions, unfamiliar terms, or anxiety—can distort it. Feedback such as facial expressions and questions helps you adapt.\n\n## Example\nInstead of saying 'I want to talk about education,' say 'By the end of this talk, you will know three ways to study more effectively using active recall.'\n\n## Practice\nWrite one sentence describing the purpose of a two-minute talk. Name your intended audience and list two things they already know.\n\n## Check your understanding\n1. Why does audience analysis change how you explain an idea?\n2. What is the difference between a topic and a specific speaking purpose?"],["Understanding Your Audience and Your Speaking Goal","# Understanding Your Audience\nGood speakers prepare for people, not merely for slides. Before writing, ask who will attend, why they are listening, what they already believe, and which examples will feel relevant.\n\n## Four audience questions\n1. **Who?** Age, role, familiarity with the subject, and language preferences.\n2. **Why now?** What problem or opportunity brought them together?\n3. **What matters?** What consequences or benefits will they care about?\n4. **What next?** What realistic action should follow the speech?\n\n## Inform, persuade, or inspire\nAn informative talk explains a process or concept. A persuasive talk argues for a decision using evidence and reasoning. An inspirational talk motivates listeners through a credible vision and relatable stories. A single talk may contain all three, but choose one primary goal.\n\n## Example\nFor a talk about internships, first-year students may need a definition and starting steps. Final-year students may value application deadlines, portfolio examples, and interview preparation.\n\n## Practice\nChoose one topic and outline two different introductions: one for secondary-school students and one for university lecturers.\n\n## Reflection\nHow would you change your vocabulary and examples without changing the truth of your message?"]]],["Planning and Structuring a Speech",[["Building a Clear Introduction, Body and Conclusion","# Structure That Helps Listeners Follow\nA well-structured speech makes it easy to understand what matters and remember it later.\n\n## Introduction\nStart with a relevant question, brief story, surprising observation, or problem. State your central idea and preview the two or three main points. Avoid an opening that promises more than you can deliver.\n\n## Body\nUse two or three distinct main points. For each point: make a claim, explain it, illustrate it, and connect it back to the purpose. Use transitions such as 'First,' 'In contrast,' and 'This brings us to...'.\n\n## Conclusion\nSignal that you are closing. Restate the central message in fresh words, summarize the strongest points, and give a specific takeaway or call to action. Do not introduce a completely new argument.\n\n## Example outline: Protecting Your Online Accounts\nIntroduction: A short example of a stolen account.\nPoint 1: Use unique passwords.\nPoint 2: Enable multi-factor authentication.\nPoint 3: Recognize phishing messages.\nConclusion: Ask listeners to secure one important account today.\n\n## Practice\nDraft a 90-second speech outline with one opening, three points, transitions, and one closing sentence."],["Research, Evidence and Storytelling","# Make Your Ideas Credible and Memorable\nStrong speeches combine clear reasoning with concrete examples. Evidence helps an audience trust your claims; stories help them understand why those claims matter.\n\n## Research responsibly\nPrefer original reports, credible institutions, and primary observations. Record the source, publication date, and relevant context. A statistic without its population or time period can mislead. Never invent data or quotations to make a speech impressive.\n\n## Use a claim–evidence–meaning pattern\n**Claim:** State the point.\n**Evidence:** Offer a verified statistic, example, demonstration, or expert explanation.\n**Meaning:** Explain how the evidence supports the point and why listeners should care.\n\n## A useful story arc\nSituation → challenge → decision → result → lesson. Keep the story short and directly connected to the message. Protect other people's privacy when using real experiences.\n\n## Avoid common weaknesses\nDo not overload the audience with numbers, use an anecdote as proof of a universal claim, or read citations without explaining them.\n\n## Practice\nWrite one claim about a student-life issue. Identify a source you could verify, then create a 60-word illustrative story clearly labeled as hypothetical."]]],["Voice, Body Language and Confident Delivery",[["Voice Control: Pace, Pauses and Clarity","# Use Your Voice as a Tool\nEffective vocal delivery is understandable and varied, not necessarily loud or dramatic.\n\n## Five techniques\n**Pace:** Speak slowly enough for listeners to process unfamiliar ideas. Speed up slightly for a familiar story and slow down for an important explanation.\n\n**Pauses:** Pause after a key point, before a reveal, or when moving to a new section. Silence can improve comprehension.\n\n**Volume:** Project your voice to the back of the room without shouting. Use a microphone when needed.\n\n**Articulation:** Pronounce endings clearly, especially technical terms and names. Practice difficult phrases aloud.\n\n**Emphasis:** Stress the words that carry the meaning: 'We need to act **today**,' rather than treating every word equally.\n\n## Warm-up routine\nBreathe gently, relax your shoulders and jaw, read a paragraph aloud, then record 30 seconds. Listen for rushed phrases and unclear endings.\n\n## Practice\nRead this sentence three times, emphasizing a different word each time: 'Students can develop leadership skills through practice.' Explain how the meaning changes."],["Body Language, Eye Contact and Managing Nerves","# Communicate With Your Whole Presence\nListeners notice posture, gestures, facial expression, and eye contact. Your goal is congruence: let nonverbal cues support your words.\n\n## Practical body language\nStand or sit with balanced posture. Use natural gestures to illustrate size, sequence, or contrast. Avoid repetitive movements that distract from the message. Look toward different sections of the audience, rather than staring at one person or the floor. In online presentations, occasionally look toward the camera.\n\n## Handling anxiety\nNervousness is common. Preparation and repeated exposure often help. Rehearse the first 20 seconds until it feels familiar. Take a comfortable breath before beginning. If you lose your place, pause, check your notes, and continue; an apology is rarely necessary.\n\n## Recovery plan\nIf equipment fails, explain the key idea without the slide. If someone interrupts, acknowledge the question and decide whether to answer immediately or at the end. If you make an error, correct it briefly and move on.\n\n## Practice\nRecord a one-minute introduction. Review your posture, eye contact, gestures, and speaking pace. Identify one strength and one improvement for the next attempt."]]],["Presentations, Persuasion and Questions",[["Visual Aids and Persuasive Communication","# Support Your Speech Without Hiding Behind Slides\nSlides, charts, objects, and demonstrations should clarify your message, not replace your explanation.\n\n## Design principles\nUse one main idea per slide. Choose readable type and strong contrast. Label charts clearly and explain what they show. Avoid walls of text and decorative animations that compete with your voice. Provide verbal descriptions of essential visuals for accessibility.\n\n## Persuasion with integrity\nA persuasive talk needs a clear proposal, credible reasons, fair treatment of objections, and a realistic next step. Distinguish facts from interpretations and acknowledge uncertainty where it exists.\n\n## Example: Student Skills Workshop\nProposal: Offer a monthly public-speaking practice session.\nReason: Students need opportunities to rehearse and receive feedback.\nObjection: 'There is not enough time.'\nResponse: Pilot a 30-minute session and assess attendance and feedback before expanding.\n\n## Practice\nCreate a three-slide outline: problem, evidence and proposal. Write what you will say that is *not* written on each slide."],["Handling Questions and Speaking in Groups","# Turn Questions Into Dialogue\nQuestions show where listeners need clarification, disagree, or want to apply your ideas. Handle them respectfully and keep the conversation productive.\n\n## A reliable response method\n1. Listen without interrupting.\n2. Restate the question if it is unclear.\n3. Answer directly with one or two supporting points.\n4. Check whether the answer addressed the question.\n\nIf you do not know, say so and explain how you would verify the answer. Never fabricate evidence under pressure.\n\n## Difficult situations\nFor an off-topic question, offer to discuss it afterward. For a hostile question, respond to the substance rather than the tone. For a long question, identify the central issue before answering.\n\n## Group presentations\nAgree on one narrative, allocate sections by expertise, rehearse handovers, and make slide ownership clear. Every member should understand the full proposal well enough to answer basic questions.\n\n## Practice\nWrite concise answers to: 'What evidence supports your idea?' and 'What would you change if your proposal failed?'"]]],["Practice, Feedback and Final Speech",[["Rehearsal and Constructive Feedback","# Improvement Comes From Deliberate Practice\nReading about speaking is useful; skill grows when you actually speak, review, and revise.\n\n## A five-round rehearsal plan\nRound 1: Explain the main idea without notes.\nRound 2: Follow your outline and check transitions.\nRound 3: Record yourself and evaluate clarity, timing, and pace.\nRound 4: Rehearse with a listener and request specific feedback.\nRound 5: Deliver the revised speech under realistic time conditions.\n\n## Feedback rubric\nScore each dimension from 1 (needs work) to 5 (strong): clear purpose, logical structure, supporting evidence, vocal clarity, audience connection, and effective conclusion.\n\nAsk observers for one concrete example of something effective and one actionable improvement. 'Be more confident' is less useful than 'Pause for two seconds after the opening question.'\n\n## Practice\nUse the rubric on a two-minute recorded speech. Choose the lowest-scoring dimension and make one specific change before recording again."],["Final Assignment: Deliver Your Three-Minute Speech","# Final Speaking Challenge\nYou have learned how to identify a purpose, understand an audience, structure a message, use evidence, deliver confidently, and respond to questions. Now combine those skills.\n\n## Your task\nPrepare and deliver a three-minute informative or persuasive speech on a meaningful topic. Suitable examples include digital safety, career readiness, community service, financial literacy, or the value of lifelong learning.\n\n## Required elements\n- A clear purpose and named audience.\n- An engaging opening and one-sentence central message.\n- Two or three organized main points with relevant support.\n- At least one verified example or source, where factual claims require evidence.\n- A concise conclusion with a memorable takeaway.\n- One rehearsal recording or live practice attempt.\n\n## Self-assessment\nEvaluate your speech from 1 to 5 for structure, clarity, evidence, vocal delivery, audience engagement, and timing. Write two strengths and two improvements.\n\n## Completion and certificate\nAfter reading and marking all ten lessons complete across the five modules, the platform records course completion and automatically attempts to issue a UCC SKILLSHUB certificate of completion through its existing certificate system. The reading completion certificate confirms completion of the course content; it is not an independently assessed professional speaking qualification.\n\n## Reflection\nWhat single speaking habit will you practice every week over the next month?"]]]]

def seed(apps, schema_editor):
    Course = apps.get_model("courses", "Course")
    Category = apps.get_model("courses", "CourseCategory")
    Module = apps.get_model("courses", "CourseModule")
    Lesson = apps.get_model("courses", "Lesson")
    User = apps.get_model("accounts", "User")
    owner = User.objects.filter(is_superuser=True).order_by("pk").first()
    if owner is None:
        owner = User.objects.filter(role__in=["administrator","facilitator","lecturer"]).order_by("pk").first()
    if owner is None:
        return
    category, _ = Category.objects.get_or_create(slug="communication", defaults={"name":"Communication","description":"Communication and interpersonal skills","is_active":True})
    course, created = Course.objects.get_or_create(slug="public-speaking-foundations",defaults={
        "title":"Public Speaking: Speak with Confidence",
        "description":"A five-module reading course covering speech planning, audience analysis, confident delivery, visual aids, questions and practical rehearsal. Complete all lessons to earn a UCC SKILLSHUB certificate of completion.",
        "category":category,"created_by":owner,"difficulty":"beginner","estimated_duration_minutes":180,
        "learning_objectives":["Plan an audience-focused speech","Organize a clear argument","Use voice and body language effectively","Handle questions confidently","Rehearse and evaluate a short speech"],
        "prerequisites":[],"status":"published","certificate_eligible":True
    })
    if not created:
        Course.objects.filter(pk=course.pk).update(status="published",certificate_eligible=True)
    for order, (title, lessons) in enumerate(MODULES, 1):
        module, _ = Module.objects.get_or_create(course=course,order=order,defaults={"title":title,"description":"Read both lessons and mark each complete to progress."})
        for lesson_order, (lesson_title, content) in enumerate(lessons, 1):
            Lesson.objects.get_or_create(module=module,order=lesson_order,defaults={
                "title":lesson_title,"description":"Reading lesson with explanations, examples and practice activities.",
                "content_type":"text","content":content,"duration_minutes":18,"is_preview":order==1 and lesson_order==1
            })

